const store = new Map();               // key -> { value, expires }
const MAX = 500, TTL = 60_000;

export function cached(key, load) {
  const hit = store.get(key);
  if (hit && hit.expires > performance.now()) return hit.value;
  const value = load(key);
  if (store.size >= MAX) store.delete(store.keys().next().value);  // oldest first
  store.set(key, { value, expires: performance.now() + TTL });
  return value;
}
